// Real-size JPEGs from fixtures/snag-photos. Generated test cards, not colour squares.
// ffmpeg testsrc / testsrc2 / smptebars, longest edge 1600, no GPS EXIF.

const beforeWide = ''

const afterWide = ''

const beforeTall = ''

const bars = ''

export const SNAG_JPEG_BASE64 = {
  beforeWide,
  afterWide,
  beforeTall,
  bars,
} as const

export type SnagJpegName = keyof typeof SNAG_JPEG_BASE64

export function snagJpegBytes(name: SnagJpegName): Uint8Array {
  const raw = SNAG_JPEG_BASE64[name]
  if (typeof Buffer !== 'undefined') return new Uint8Array(Buffer.from(raw, 'base64'))
  const binary = atob(raw)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i)
  return bytes
}

export function snagJpegDataUrl(name: SnagJpegName): string {
  return `data:image/jpeg;base64,${SNAG_JPEG_BASE64[name]}`
}
